message.baseline:
// The Runner interface, the loop building blocks, and the default Agent
// runner. The runner owns the loop: tool execution, correlation, budgets,
// journal writes, and the typed parse of the final output.
// Mirrors _planv2/pages/02_guides/02_specs_and_runners/02_the_default_runner.md.

interface Runner {
    /// The error surface of this runner (`never` if the runner cannot throw).
    type Error = never;

    /// Execute one spec to completion. `Out` lives on the method and is
    /// inferred from the spec argument, so no call site needs to name it.
    function run<Out>(self, spec: FunctionSpec<Out>) -> RunResult<Out> throws Self.Error;
}

class RunResult<Out> {
    value: Out,
    journal: Journal,
    usage: root.events.Usage,
}

/// The default runner. A spec-mode LLM function's direct call runs
/// `Agent.new(client = client).run(Fn@spec(...)).value`; construct it
/// yourself to set the other fields (`$` call-site parameters are a future
/// phase).
///
/// The class itself is not generic: none of its configuration involves the
/// output type. `Out` lives on `run`, where it is inferred from the spec
/// argument, so no call site needs to name it.
class Agent {
    max_steps: int,
    // Total model invocations allowed for one schema candidate. The default
    // preserves the existing initial attempt plus one correction re-ask.
    schema_attempts: int,
    client: Client?,
    tool_errors: root.tools.ErrorMode,
    on_event: ((root.events.Event) -> void throws never)?,

    function new(
        max_steps: int = 12,
        schema_attempts: int = 2,
        client: Client? = null,
        tool_errors: root.tools.ErrorMode = root.tools.ErrorMode.Report,
        on_event: ((root.events.Event) -> void)? = null,
    ) -> Agent {
        if (schema_attempts < 1) {
            throw baml.errors.InvalidArgument {
                message: "Agent schema_attempts must be at least 1",
            }
        }
        Agent {
            max_steps: max_steps,
            schema_attempts: schema_attempts,
            client: client,
            tool_errors: tool_errors,
            on_event: root.events.guard(on_event),
        }
    }

    function _validated_schema_attempts(self) -> int {
        if (self.schema_attempts < 1) {
            throw baml.errors.InvalidArgument {
                message: "Agent schema_attempts must be at least 1",
            }
        }
        self.schema_attempts
    }

    /// (internal) Execute one call: validate, dispatch, append the correlated result.
    /// A Raise-mode failure throws ToolFailedError after ToolFailed lands.
    function _run_one_tool(
        self,
        tb: root.tools.Toolbox,
        call: root.content.ToolUse,
        j: Journal,
    ) -> void {
        match (tb.get(call.name)) {
            let t: root.tools.Tool => {
                let outcome: string? = t.call(call.args) catch_all (e) {
                    _ => {
                        j.append_all(
                            [root.events.ToolFailed { id: call.id, message: e.to_string() }],
                        );
                        // the per-tool setting wins; null inherits the run's mode
                        if ((t.on_error ?? self.tool_errors) == root.tools.ErrorMode.Raise) {
                            let classified = match (e) {
                                let f: root.errors.Failure => f,
                                _ => null,
                            };
                            throw root.errors.ToolFailedError {
                                id: call.id,
                                name: call.name,
                                message: e.to_string(),
                                cause: classified,
                            }
                        } else {
                            null
                        }
                    },
                };
                if let output: string = outcome {
                    j.append_all([root.events.ToolCompleted.new(call.id, output)]);
                }
                null
            },
            null => {
                j.append_all(
                    [
                        root.events.ToolFailed {
                            id: call.id,
                            message: `tool is not in the active toolbox: ${call.name}`,
                        },
                    ],
                );
                null
            },
        }
    }

    /// (internal) Does this turn carry content a media-shaped `Out` can be built from?
    /// Mirrors the `Ok(None)` condition of sys_llm's
    /// `parse_llm_output_for_target`: nothing to build from means fall back to
    /// the ordinary text parse. Always false when `Out` holds no media.
    function _has_media_output<Out>(self, turn: ModelTurn) -> bool {
        let shape = root.internal._media_shape(reflect.Type.of<Out>());
        let form = shape.split(":").at(0) ?? "";
        if (form == "") {
            return false;
        }
        if (form == "mixed" || form == "mixedlist") {
            return root.internal._media_mixed_parts(turn).length() > 0;
        }
        root.internal._media_of_kind(turn, shape.split(":").at(1) ?? "").length() > 0
    }

    /// (internal) Build a media-shaped `Out` from the turn's content blocks. Only called
    /// when `_has_media_output` holds; the shape-specific errors below are the
    /// ported sys_llm messages, thrown after the turn is already on the record.
    function _media_value<Out>(self, turn: ModelTurn, provider: string) -> Out {
        let t = reflect.Type.of<Out>();
        let shape = root.internal._media_shape(t);
        let form = shape.split(":").at(0) ?? "";
        let kind = shape.split(":").at(1) ?? "";
        let payload = match (form) {
            "mixedlist" => {
                let items: baml.json.json = root.internal._media_mixed_parts(turn);
                items
            },
            "mixed" => {
                let items = root.internal._media_mixed_parts(turn);
                if (items.length() == 1) {
                    let only: baml.json.json = null;
                    for (let i in items) {
                        only = i;
                    }
                    only
                } else if (root.internal._media_all_text(items)) {
                    // several plain text parts collapse into one string
                    root.internal._media_join_text(items)
                } else {
                    throw root.errors.ParseFailed {
                        provider: provider,
                        raw_output: `Expected one text or image output for ${t.to_string()}, got ${items.length()} parts. Use (image | string)[] to preserve mixed outputs.`,
                    }
                }
            },
            "list" => {
                root.internal._media_reject_mixed(turn, kind, provider);
                let items: baml.json.json = root.internal._media_of_kind(turn, kind);
                items
            },
            _ => {
                let parts = root.internal._media_of_kind(turn, kind);
                root.internal._media_reject_mixed(turn, kind, provider);
                if (parts.length() != 1) {
                    throw root.errors.ParseFailed {
                        provider: provider,
                        raw_output: if (form == "one") {
                            `Expected exactly one ${kind} output, got ${parts.length()}. Use ${kind}[] for multiple outputs.`
                        } else {
                            `Expected zero or one ${kind} output for ${t.to_string()}, got ${parts.length()}. Use ${kind}[] for multiple outputs.`
                        },
                    }
                }
                let only: baml.json.json = null;
                for (let p in parts) {
                    only = p;
                }
                only
            },
        };
        baml.json.from_json<Out>(payload) catch_all (e) {
            _ => {
                throw root.errors.ParseFailed {
                    provider: provider,
                    raw_output: `the ${kind} output did not fit ${t.to_string()}: ${e.to_string()}`,
                }
            },
        }
    }

    function _parses<Out>(self, turn: ModelTurn, candidate: string) -> bool {
        // A media-shaped `Out` is satisfied by the turn's blocks. When the turn
        // carries NONE, this falls through to the ordinary text parse rather
        // than declaring failure — that is sys_llm's `Ok(None)` -> SAP path
        // (`lib.rs:594-645`), and SAP is what turns a media-less answer into
        // `null` for `image?` and `[]` for `image[]`. Short-circuiting to
        // `false` here made those shapes unrepresentable: the runner re-asked
        // and then raised ParseFailed on a perfectly valid absence. Only a
        // required `image` genuinely fails the text parse.
        if (self._has_media_output<Out>(turn)) {
            return true;
        }
        let _ = baml.sap.parse<Out>(candidate) catch_all (e) {
            _ => {
                return false;
            },
        };
        true
    }

    /// (internal) One accepted model turn, with the within-turn repair loop: when a
    /// Complete turn's candidate does not parse, commit the failed turn and a
    /// correction request as ordinary events and invoke again, under a fixed
    /// attempt budget. Everything that happened is on the record; a repair
    /// attempt does not consume a step. Token usage of every attempt is
    /// added to `total`.
    function _attempt_turn<Out>(
        self,
        c: Client,
        spec: FunctionSpec<Out>,
        j: Journal,
        total: root.events.Usage,
        attempts_left: int,
    ) -> ModelTurn {
        let turn = c.invoke(
            ModelTurnInput {
                prompt: spec.prompt_template,
                journal: j,
                toolbox: spec.tools(),
                output_type: spec.output_type(),
            },
        );
        if let u: root.events.Usage = turn.usage {
            total.input_tokens += u.input_tokens;
            total.output_tokens += u.output_tokens;
            if let ci: int = u.cached_input_tokens {
                total.cached_input_tokens = (total.cached_input_tokens ?? 0) + ci;
            }
            if let rt: int = u.reasoning_tokens {
                total.reasoning_tokens = (total.reasoning_tokens ?? 0) + rt;
            }
        }
        // every attempt commits: the journal is the complete record
        let batch: root.events.Event[] = [root.events.AssistantMessage { content: turn.content, client_id: c.id() }];
        // wire records ride the journal: failed legs first, selected last
        for (let call in turn.calls) {
            batch.push(call);
        }
        for (let u in turn.tool_uses()) {
            batch.push(root.events.ToolRequested { id: u.id, name: u.name, args: u.args });
        }
        if let u: root.events.Usage = turn.usage {
            batch.push(u);
        }
        let candidate = turn.terminal_text() ?? "";
        let accepted = turn.tool_uses().length() > 0
            || turn.stop_reason == root.content.StopReason.MaxTokens
            || turn.stop_reason == root.content.StopReason.Refused
            || self._parses<Out>(turn, candidate);
        if (accepted) {
            j.append_all(batch);
            // terminal wire outcomes are thrown here, with the turn on the record
            match (turn.stop_reason) {
                root.content.StopReason.MaxTokens => {
                    throw root.errors.FinishReasonError {
                        provider: c.id(),
                        finish_reason: turn.stop_reason,
                        raw_output: candidate,
                    }
                },
                root.content.StopReason.Refused => {
                    throw root.errors.Refused { provider: c.id(), reason: "the model declined to answer", raw_body: null }
                },
                _ => null,
            };
            turn
        } else if (attempts_left > 1) {
            batch.push(
                root.events.UserMessage.new(
                    "The reply did not match the required schema. Answer again with only the corrected value.",
                ),
            );
            j.append_all(batch);
            self._attempt_turn<Out>(c, spec, j, total, attempts_left - 1)
        } else {
            j.append_all(batch);
            throw root.errors.ParseFailed { provider: c.id(), raw_output: candidate }
        }
    }

    /// (internal) Emit any events appended since `seen` to on_event; returns the new count.
    function _emit_from(self, j: Journal, seen: int) -> int {
        let entries = j.entries();
        if let cb: (root.events.Event) -> void throws never = self.on_event {
            let i = seen;
            while (i < entries.length()) {
                if let e: root.events.Event = entries.at(i) {
                    cb(e);
                }
                i = i + 1;
            }
        }
        entries.length()
    }

    implements Runner {
        // Cancellation is absent for the same reason it is absent from
        // `ai.errors.InvokeError`: a panic unwinds past the error channel
        // rather than travelling in it.
        type Error = baml.errors.InvalidArgument
            | baml.errors.Timeout
            | baml.errors.UnknownError
            | reflect.errors.CompilationError
            | root.errors.Failure;

        function run<Out>(self, spec: FunctionSpec<Out>) -> RunResult<Out> {
            let schema_attempts = self._validated_schema_attempts();
            let selected = self.client ?? spec.default_client;
            let j = Journal.new(spec);
            let seen = self._emit_from(j, 0);
            let steps = 0;
            let total = root.events.Usage {
                input_tokens: 0,
                output_tokens: 0,
                cached_input_tokens: null,
                reasoning_tokens: null,
            };
            // the futility breaker: identical repeated failures stop the run
            let fail_counts: map<string, int> = {};
            while (steps < self.max_steps) {
                // Repair re-asks happen inside the step and share this total
                // schema-attempt budget.
                let turn = self._attempt_turn<Out>(selected, spec, j, total, schema_attempts);
                steps = steps + 1;
                seen = self._emit_from(j, seen);
                let calls = turn.tool_uses();
                if (calls.length() > 0) {
                    let before = j.entries().length();
                    // execute concurrently; each call appends its correlated result
                    let futures = calls.map((call) -> {
                        spawn { self._run_one_tool(spec.tools(), call, j) }
                    });
                    let _ = await baml.future.all(futures) catch_all (e) {
                        _ => {
                            // A Raise-mode tool failure: its ToolFailed event is
                            // already on the record; deliver it before the error
                            // propagates so listeners never miss journal events.
                            seen = self._emit_from(j, seen);
                            throw e
                        },
                    };
                    seen = self._emit_from(j, seen);
                    // Reporting a failure lets the model adapt; repeating the
                    // IDENTICAL failing call is futile, and each step can be
                    // expensive. Three identical failures end the run.
                    let entries = j.entries();
                    let i = before;
                    while (i < entries.length()) {
                        if let f: root.events.ToolFailed = entries.at(i) {
                            let failed_call = calls.find((one: root.content.ToolUse) -> {
                                one.id == f.id
                            });
                            if let known: root.content.ToolUse = failed_call {
                                let key = `${known.name}|${f.message}`;
                                let n = (fail_counts.get(key) ?? 0) + 1;
                                let _ = fail_counts.set(key, n);
                                if (n >= 3) {
                                    throw root.errors.ToolFailedError {
                                            id: known.id,
                                            name: known.name,
                                            message: `the same tool call failed ${n} times; stopping the run: ${f.message}`,
                                            cause: null,
                                        }
                                }
                            }
                        }
                        i = i + 1;
                    }
                } else {
                    let candidate = turn.terminal_text() ?? "";
                    // A media-shaped Out comes from the turn's media blocks;
                    // everything else, including a media Out the turn produced
                    // no media for, goes through the ordinary text parse. That
                    // second branch is REACHABLE for a media Out and is how
                    // absence is expressed: SAP answers `null` for `image?` /
                    // `image[]?` and `[]` for `image[]`, and only a required
                    // `image` fails there (`_parses` agrees, by construction).
                    let value = if (self._has_media_output<Out>(turn)) {
                        self._media_value<Out>(turn, selected.id())
                    } else {
                        baml.sap.parse<Out>(candidate) catch_all (e) {
                            _ => {
                                throw root.errors.ParseFailed { provider: selected.id(), raw_output: candidate }
                            },
                        }
                    };
                    let value_json = baml.json.to_json(value) catch_all (e) {
                        _ => {
                            throw baml.errors.UnknownError.with_message<never>(
                                    e,
                                    "final value serialization failed",
                                )
                        },
                    };
                    j.append_all(
                        [root.events.FinalProduced { value_json: baml.json.stringify(value_json) }],
                    );
                    seen = self._emit_from(j, seen);
                    return RunResult { value: value, journal: j, usage: total };
                }
            }
            throw root.errors.StepBudgetExceeded { steps: steps }
        }
    }
}

// The client boundary: one operation. A client renders the input into its
// wire format, makes one call, and returns canonical content. It never
// writes the journal, executes a tool, or parses the output type.
// Mirrors _planv2/pages/02_guides/03_clients/02_the_client_interface.md.

class ModelTurnInput {
    // The bound prompt template. The client supplies the output-format schema
    // handle and receives one structural prompt.
    prompt: (OutputFormat) -> Prompt throws root.errors.PromptRenderError,
    journal: Journal,
    toolbox: root.tools.Toolbox,
    output_type: reflect.Type,
}

class ModelTurn {
    content: root.content.ModelBlock[],
    stop_reason: root.content.StopReason,
    usage: root.events.Usage?,
    // Every HTTP exchange behind this turn, oldest first: failed legs from
    // retry/fallback wrappers, then the selected call (selected: true).
    calls: root.events.LLMCall[],

    /// The terminal Text block — the final candidate the runner parses.
    function terminal_text(self) -> string? {
        let out: string? = null;
        for (let b in self.content) {
            if let t: root.content.Text = b {
                out = t.text;
            }
        }
        out
    }

    /// The media payloads the turn produced, in order. A media-shaped output
    /// type is built from these instead of from the terminal text.
    function media(self) -> MediaPart[] {
        let out: MediaPart[] = [];
        for (let b in self.content) {
            if let m: root.content.Media = b {
                out.push(m.media);
            }
        }
        out
    }

    /// The ToolUse blocks of the turn, in order.
    function tool_uses(self) -> root.content.ToolUse[] {
        let out: root.content.ToolUse[] = [];
        for (let b in self.content) {
            if let u: root.content.ToolUse = b {
                out.push(u);
            }
        }
        out
    }
}

interface Client {
    function id(self) -> string throws never;
    /// Render the provider request shape without performing I/O. Reliability
    /// wrappers use this as a stable request-shape preview: they do not sleep,
    /// rotate, or try fallback members while rendering.
    function render(
        self,
        input: ModelTurnInput,
    ) -> baml.http.Request throws root.errors.InvokeError;
    function invoke(self, input: ModelTurnInput) -> ModelTurn throws root.errors.InvokeError;
}

/// Constructs the literal type matching exactly a string, int, bigint, or bool value.
//baml:mut_vm
function new(value: string | int | bigint | bool) -> Type throws never {
    $rust_function
}

/// A literal-kind view of a `type` value. Users never construct this class.
class Type {
    /// The wrapped `type` value. Private by invariant: reflection natives are
    /// its only readers, and each kind method panics if the held type no longer
    /// classifies as this view's kind.
    _ty: reflect.Type,

    implements reflect.TypeView {
        //baml:vm
        //baml:fallible
        function as_type(self) -> reflect.Type throws never {
            $rust_function
        }
    }

    /// Returns the value represented by this literal type.
    //baml:mut_vm
    //baml:fallible
    function value(self) -> string | int | bigint | bool throws baml.errors.InvalidArgument {
        $rust_function
    }
}

/// One parameter of a function signature (BEP-062).
class Arg {
    /// The parameter's name. When the callable carries no name for a
    /// positional parameter (a host callable from a language without
    /// parameter-name introspection), this is the placeholder `$argN` for
    /// position N. `$` cannot appear in a user identifier, so a placeholder
    /// can never collide with a declared parameter or named-argument key.
    name: string,
    /// The parameter's type.
    type: reflect.Type,
}

/// Metadata baked into reflected schema definitions.
class Meta {
    alias: string?,
    description: string?,
    docstring: string?,
    other: map<string, string>,
}

/// A value paired with schema metadata. For type values this lets metadata be
/// attached without mutating the minted definition.
class WithMeta<T> {
    ty: T,
    alias: string?,
    description: string?,
    docstring: string?,
    other: map<string, string>,
}

/// A source range attached to a compiler diagnostic. Compile- and eval-door
/// diagnostics carry their source range; structured construction diagnostics
/// report `span = null`, including constructors invoked from BAML.
class Span {
    file: string?,
    start: int,
    end: int,
}

/// A UTF-8 byte range inside a diagnostic headline or annotation label.
class DiagnosticHighlight {
    start: int,
    end: int,
    kind: "identifier.type"
        | "identifier.function"
        | "identifier.field"
        | "identifier.variable"
        | "identifier.enum_variant"
        | "identifier.attribute"
        | "type_expression"
        | "code",
}

/// A primary or secondary source annotation. `message = null` represents a
/// span-only annotation.
class DiagnosticAnnotation {
    span: Span,
    message: string?,
    message_highlights: DiagnosticHighlight[],
    is_primary: bool,
}

/// Additional source information associated with a diagnostic.
class DiagnosticRelatedInfo {
    span: Span,
    message: string,
    message_highlights: DiagnosticHighlight[],
    file_path: string?,
}

/// The stable structured diagnostic surfaced by reflection constructors and
/// runtime compilation. `message` retains the historical flattened
/// headline-plus-primary-label representation; use `headline` and
/// `primary_label` when those parts must be inspected independently.
class Diagnostic {
    code: string,
    span: Span?,
    message: string,
    /// Severity retained from the compiler diagnostic stream.
    severity: "error" | "warning" | "info",
    /// Compiler stage that emitted a source diagnostic. Runtime-generated
    /// diagnostics which do not belong to a compiler stage report `null`.
    phase: ("parse" | "hir" | "validation" | "type")?,
    headline: string,
    primary_label: string?,
    message_highlights: DiagnosticHighlight[],
    annotations: DiagnosticAnnotation[],
    related_info: DiagnosticRelatedInfo[],
}

/// Common identity-preserving surface shared by every reflection kind view.
interface TypeView {
    /// The `type` value this view wraps, restoring the unnarrowed type.
    function as_type(self) -> reflect.Type throws never;
}

/// The closed set of reflection views for a runtime `type` value.
type TypeKind = reflect.class.Type
    | reflect.enum.Type
    | reflect.union.Type
    | reflect.literal.Type
    | reflect.array.Type
    | reflect.map.Type
    | reflect.interface.Type
    | reflect.primitive.Type
    | reflect.function.Type;

/// Implemented automatically by every function value, with its parameter
/// list erased. `Returns` pins the held function's return type and `Throws`
/// its error type; both default to `unknown`, so a bare `AnyFunction`
/// accepts any function. A compiler builtin: it cannot be implemented by
/// hand, cannot be used as a generic bound, and declares no methods. Call
/// the held function through `reflect.call_any`; read its signature with
/// `reflect.signature`.
interface AnyFunction {
    /// The held function's return type. `unknown` accepts any return.
    type Returns = unknown;
    /// The held function's error type. `unknown` accepts any throws clause.
    type Throws = unknown;
}

/// A read-only reflected view implemented automatically by class values.
///
/// Narrow an opaque value with `let value: reflect.AnyClass = opaque else { ... }`
/// before using this surface. Ordinary class instances implement it, including
/// runtime-minted classes. Of the sealed reflection-kind views, only
/// `reflect.class.Type` implements it.
interface AnyClass {
    /// Read a field as `T`. A missing field returns `null`; use `has_field` to
    /// distinguish that case from a present field whose value is null.
    function get<T>(self, name: string) -> T? throws reflect.errors.TypeMismatch {
        if (!self.has_field(name)) {
            return null;
        }
        // NOTE: spelled with `let … else` rather than `self.get_field(name)?.value<T>()`
        // because an optional-chained call does not thread `T` to the callee.
        let field: reflect.class.Field = self.get_field(name) else {
            return null;
        };
        field.value<T>()
    }

    /// Return a value-bound field handle, or `null` when no such field exists.
    function get_field(self, name: string) -> reflect.class.Field? throws never {
        let class_type: reflect.class.Type = reflect.Type.of_value(self).as_class() else {
            return null;
        };
        for (let field in class_type.fields()) {
            if (field.name == name) {
                return reflect.class.Field {
                    name: field.name,
                    type: field.type,
                    meta: field.meta,
                    _owner: self,
                };
            }
        }
        null
    }

    /// Whether this value's runtime class declares a field called `name`.
    /// `false` when the runtime type is not a class.
    function has_field(self, name: string) -> bool throws never {
        let class_type: reflect.class.Type = reflect.Type.of_value(self).as_class() else {
            return false;
        };
        for (let field in class_type.fields()) {
            if (field.name == name) {
                return true;
            }
        }
        false
    }

    /// Reflected fields bound to this value for `Field.value<T>()`.
    function list_fields(self) -> reflect.class.Field[] throws never {
        let class_type: reflect.class.Type = reflect.Type.of_value(self).as_class() else {
            return [];
        };
        let fields: reflect.class.Field[] = [];
        for (let field in class_type.fields()) {
            fields.push(
                reflect.class.Field {
                    name: field.name,
                    type: field.type,
                    meta: field.meta,
                    _owner: self,
                },
            )
        }
        fields
    }

    /// The rendered name of this value's concrete runtime type.
    function name(self) -> string throws never {
        reflect.Type.of_value(self).to_string()
    }

    /// This value's concrete runtime type.
    function type(self) -> reflect.Type throws never {
        reflect.Type.of_value(self)
    }

    /// The class declaration's schema metadata, or empty metadata when the
    /// runtime type is not a class.
    function attributes(self) -> reflect.Meta throws never {
        let class_type: reflect.class.Type = reflect.Type.of_value(self).as_class() else {
            return reflect.Meta { alias: null, description: null, docstring: null, other: {} };
        };
        class_type.meta()
    }
}

implement<T> AnyClass for T {}

/// The runtime signature of a function value, reconstructed from the value
/// itself (BEP-062). Positional (required) parameters appear in `args` in
/// declaration order; named/optional parameters appear in `opts`, keyed by
/// name. A bound method reports its receiver-adjusted signature (no `self`).
class Signature {
    /// The name the function was declared with; null for host callables and
    /// compiler-synthesized callables (including lambdas).
    name: string?,
    /// Positional (required) parameters, in order.
    args: Arg[],
    /// Named/optional parameters, keyed by parameter name.
    opts: map<string, Arg>,
    /// The return type.
    returns: reflect.Type,
    /// The error type; `never` if the function cannot throw.
    errors: reflect.Type,
    /// The function's doc comment (joined `///` lines); null when absent.
    docstring: string?,
}

/// Thrown by `reflect.call_any` when the supplied arguments or returned value
/// do not fit its runtime signature. `argument` names the offending key
/// (`$argN` placeholders included); a return mismatch names the
/// `reflect.call_any return value` boundary. An ill-typed value reports the
/// expected and actual types; a missing required parameter reports the
/// parameter's type and `never`; a key naming no parameter reports the
/// callee's whole function type and the value's type.
class InvalidArgumentError {
    argument: string,
    expected: reflect.Type,
    got: reflect.Type,
}

/// One-shot compiler output consumed by Package._finish or Session._finish.
class CompileArtifact {
    _inner: unknown,
}

/// An isolated runtime-compiled package.
class Package {
    _inner: unknown,

    /// The package lexically enclosing this call site.
    function current() -> Package throws never {
        $compiler_intrinsic
    }

    /// Compiles `files` into an isolated package, resolving its dependencies
    /// against `packages`.
    ///
    /// # Parameters
    ///
    /// - `files`: source text keyed by path, as the package's `baml_src`.
    /// - `packages`: packages the source may depend on, keyed by the alias it
    ///   imports them under.
    ///
    /// # Throws
    ///
    /// - `reflect.errors.CompilationError` if the source does not compile.
    /// - anything the package's top-level initialization throws, which is why
    ///   the clause is `unknown`.
    function compile(
        files: map<string, string>,
        packages: map<string, Package> = {},
    ) -> Package throws unknown {
        let artifact = Package._compile(files, packages);
        Package._finish(artifact, packages)
    }

    function _compile(
        files: map<string, string>,
        packages: map<string, Package>,
    ) -> CompileArtifact throws reflect.errors.CompilationError {
        $rust_io_function
    }

    //baml:mut_vm
    //baml:may_yield
    function _finish(
        artifact: CompileArtifact,
        packages: map<string, Package>,
    ) -> Package throws unknown {
        $rust_function
    }

    /// The exported class called `name`, or `null` if the package exports none.
    //baml:mut_vm
    function get_class(self, name: string) -> reflect.class.Type? throws never {
        $rust_function
    }

    /// The exported enum called `name`, or `null` if the package exports none.
    //baml:mut_vm
    function get_enum(self, name: string) -> reflect.enum.Type? throws never {
        $rust_function
    }

    /// The exported interface called `name`, or `null` if the package exports
    /// none.
    //baml:mut_vm
    function get_interface(self, name: string) -> reflect.interface.Type? throws never {
        $rust_function
    }

    /// Return a derived package view that exports exact runtime type values
    /// under source-visible names for subsequent Package.compile calls.
    //baml:mut_vm
    function with_types(
        self,
        types: map<string, reflect.Type | reflect.TypeView>,
    ) -> Package throws reflect.errors.CompilationError {
        $rust_function
    }
    //baml:mut_vm
    /// Extract an exported function through an ordinary function-type contract.
    ///
    /// A lookup by name has nowhere to put type arguments, so an unspecialized
    /// generic function is refused here.
    function get_function<F>(self, name: string) -> F? throws reflect.errors.CompilationError {
        $rust_function
    }

    /// Exported class types, keyed by package-local name.
    //baml:mut_vm
    function classes(self) -> map<string, reflect.class.Type> throws never {
        $rust_function
    }

    /// Exported enum types, keyed by package-local name.
    //baml:mut_vm
    function enums(self) -> map<string, reflect.enum.Type> throws never {
        $rust_function
    }

    /// Exported interface types, keyed by package-local name.
    //baml:mut_vm
    function interfaces(self) -> map<string, reflect.interface.Type> throws never {
        $rust_function
    }

    //baml:mut_vm
    /// Exported free-function signatures, keyed by package-local name.
    function functions(self) -> map<string, reflect.function.Type> throws never {
        $rust_function
    }

    /// Bundled tests as directly invocable zero-argument callables.
    //baml:mut_vm
    //baml:may_yield
    function tests(self) -> map<string, () -> null throws unknown> throws unknown {
        $rust_function
    }

    /// Diagnostics produced while compiling this package.
    //baml:mut_vm
    function diagnostics(self) -> Diagnostic[] throws never {
        $rust_function
    }
}

/// A live incremental evaluation environment. Its dependency aliases are
/// fixed at construction; every eval checks in a fresh compiler context and
/// commits successful statements to this Session's persistent runtime image.
class Session {
    _inner: unknown,

    /// Opens a session whose dependency aliases are fixed to `packages`.
    ///
    /// # Throws
    ///
    /// - `reflect.errors.CompilationError` if the dependencies do not resolve.
    function new(
        packages: map<string, Package> = {},
    ) -> Session throws reflect.errors.CompilationError {
        Session._new(packages)
    }

    //baml:mut_vm
    function _new(
        packages: map<string, Package>,
    ) -> Session throws reflect.errors.CompilationError {
        $rust_function
    }

    /// Compiles and runs `source` against this session, returning its value
    /// as `T`.
    ///
    /// Each call checks in a fresh compiler context; statements that succeed
    /// are committed to the session's persistent image and are visible to
    /// later calls. A call that throws commits nothing.
    ///
    /// # Throws
    ///
    /// - `reflect.errors.CompilationError` if `source` does not compile.
    /// - `reflect.errors.EvaluationError` if it compiles but throws when run.
    /// - `reflect.errors.SessionBusy` if the session is already evaluating.
    function eval<T>(
        self,
        source: string,
    ) -> T throws reflect.errors.CompilationError | reflect.errors.EvaluationError | reflect.errors.SessionBusy {
        let artifact = self._compile<T>(source);
        self._finish<T>(artifact) catch (cause) {
            _ => {
                throw reflect.errors.EvaluationError {
          message: _render_cause(cause),
          cause: cause,
        }
            }
        }
    }

    function _compile<T>(
        self,
        source: string,
    ) -> CompileArtifact throws reflect.errors.CompilationError | reflect.errors.SessionBusy {
        $rust_io_function
    }

    //baml:mut_vm
    //baml:may_yield
    function _finish<T>(self, artifact: CompileArtifact) -> T throws unknown {
        $rust_function
    }

    /// Diagnostics from this session's most recent `eval`.
    //baml:mut_vm
    function diagnostics(self) -> Diagnostic[] throws never {
        $rust_function
    }
}

/// (internal) Structural error rendering for `Session.eval` that keeps `reflect` a root
/// package. This is the dependency-free counterpart of `string.from`: its VM
/// implementation shares the same renderer without importing `baml`.
//baml:mut_vm
//baml:may_yield
function _render_cause(value: unknown) -> string throws never {
    $rust_function
}

/// Returns the runtime signature of `f`.
///
/// Usage:
///   let sig = reflect.signature(f)
///   sig.returns.to_string()
//baml:mut_vm
//baml:fallible
function signature(f: AnyFunction) -> Signature throws never {
    $rust_function
}

/// Calls `f` with `args`, every argument keyed by parameter name (a nameless
/// positional is addressed by its `$argN` placeholder), checked at runtime
/// against `f`'s signature: a missing required parameter, a key naming no
/// parameter, or a value that does not fit its parameter's type throws
/// `InvalidArgumentError`. The returned value is checked against `R` at the
/// same boundary (except when `R` is `unknown`). An absent optional fires the
/// callee's own default. `R` and `E` are `f`'s `Returns`/`Throws` pins, so a
/// pinned `AnyFunction<Returns = json, Throws = ToolError>` yields typed
/// results and an exhaustive catch; a bare `AnyFunction` returns `unknown`
/// and throws `unknown` (which covers `InvalidArgumentError` and
/// `reflect.errors.CompilationError`).
//baml:mut_vm
//baml:may_yield
function call_any<R, E>(
    f: AnyFunction<Returns = R, Throws = E>,
    args: map<string, unknown>,
) -> R throws E | InvalidArgumentError | reflect.errors.CompilationError {
    $rust_function
}

